// Regenerates src/lib/abi.ts from the Foundry build. Run `forge build` in ../contracts first.
import { readFileSync, writeFileSync } from "node:fs";

const read = (name) =>
  JSON.parse(readFileSync(new URL(`../../out/${name}.sol/${name}.json`, import.meta.url))).abi;

const out =
  "// Generated by scripts/gen-abi.mjs from the Foundry build. Do not edit.\n" +
  `export const gameAbi = ${JSON.stringify(read("GammaGame"))} as const;\n\n` +
  `export const hookAbi = ${JSON.stringify(read("GammaHook"))} as const;\n`;

writeFileSync(new URL("../src/lib/abi.ts", import.meta.url), out);
console.log("wrote src/lib/abi.ts");
